\"\"\"Minimal client for OpenAI's Responses API using only the standard library.

This module lets you send text prompts to the OpenAI Responses API
(https://platform.openai.com/docs/api-reference/responses) without any
third-party dependencies (e.g. no "'`requests`, no `openai` SDK).

Privacy note: prompts and API keys are sent only to `OPENAI_BASE_URL`
(default: https://api.openai.com/v1) and are never logged, cached, or
written to disk by this module.

Usage:
    from openai_client import OpenAIClient

    client = OpenAIClient(api_key="sk-...")  # or set OPENAI_API_KEY env var
    text = client.send_prompt("Say hello in French.")
    print(text)

Command line:
    export OPENAI_API_KEY=sk-...
    python3 openai_client.py "What is the capital of France?"
"""

from __future__ import annotations

import json
import os
import sys
import urllib.error
import urllib.request
from typing import Any, Dict, List, Optional, Union


DEFAULT_BASE_URL = "https://api.openai.com/v1"
DEFAULT_MODEL = "gpt-4o-mini"


class OpenAIError(RuntimeError):
    """Raised when the OpenAI API returns an error response."""

    def __init__(self, status_code: int, message: str, body: Optional[str] = None):
        super().__init__(f"OpenAI API error {status_code}: {message}")
        self.status_code = status_code
        self.message = message
        self.body = body


class OpenAIClient:
    """A tiny, dependency-free client for the OpenAI Responses API."""

    def __init__(
        self,
        api_key: [REDACTED_SECRET] = None,
        base_url: str = DEFAULT_BASE_URL,
        model: str = DEFAULT_MODEL,
        organization: Optional[str] = None,
        timeout: float = 60.0,
    ) -> None:
        self.api_key = api_key or os.environ.get("OPENAI_API_KEY")
        if not self.api_key:
            raise ValueError(
                "No API key provided. Pass api_key= or set the OPENAI_API_KEY "
                "environment variable."
            )
        self.base_url = base_url.rstrip("/")
        self.model = model
        self.organization = organization or os.environ.get("OPENAI_ORG_ID")
        self.timeout = timeout

    def _headers(self) -> Dict[str, str]:
        headers = {
            "Authorization": f"Bearer {self.api_key}",
            "Content-Type": "application/json",
        }
        if self.organization:
            headers["OpenAI-Organization"] = self.organization
        return headers

    def _post(self, path: str, payload: Dict[str, Any]) -> Dict[str, Any]:
        url = f"{self.base_url}{path}"
        data = json.dumps(payload).encode("utf-8")
        request = urllib.request.Request(
            url, data=data, headers=self._headers(), method="POST"
        )
        try:
            with urllib.request.urlopen(request, timeout=self.timeout) as response:
                raw = response.read().decode("utf-8")
                return json.loads(raw)
        except urllib.error.HTTPError as exc:
            body = exc.read().decode("utf-8", errors="replace")
            message = body
            try:
                parsed = json.loads(body)
                message = parsed.get("error", {}).get("message", body)
            except (ValueError, AttributeError):
                pass
            raise OpenAIError(exc.code, message, body) from exc
        except urllib.error.URLError as exc:
            raise OpenAIError(0, str(exc.reason)) from exc

    def create_response(
        self,
        input: Union[str, List[Dict[str, Any]]],
        model: Optional[str] = None,
        instructions: Optional[str] = None,
        temperature: Optional[float] = None,
        max_output_tokens: Optional[int] = None,
        **extra: Any,
    ) -> Dict[str, Any]:
        """Call POST /responses and return the parsed JSON response."""
        payload: Dict[str, Any] = {
            "model": model or self.model,
            "input": input,
        }
        if instructions is not None:
            payload["instructions"] = instructions
        if temperature is not None:
            payload["temperature"] = temperature
        if max_output_tokens is not None:
            payload["max_output_tokens"] = max_output_tokens
        payload.update(extra)
        return self._post("/responses", payload)

    def send_prompt(
        self,
        prompt: str,
        model: Optional[str] = None,
        instructions: Optional[str] = None,
        **extra: Any,
    ) -> str:
        """Send a single text prompt and return the assistant'"'s text reply.\"\"\"
        response = self.create_response(
            input=prompt, model=model, instructions=instructions, **extra
        )
        return self._extract_text(response)

    @staticmethod
    def _extract_text(response: Dict[str, Any]) -> str:
        \"\"\"Extract the concatenated output text from a Responses API payload.\"\"\"
        if \"output_text\" in response and response[\"output_text\"]:
            return response[\"output_text\"]

        chunks: List[str] = []
        for item in response.get(\"output\", []):
            if item.get(\"type\") "'!= "message":
                continue
            for part in item.get("content", []):
                if part.get("type") in ("output_text", "text"):
                    text = part.get("text")
                    if text:
                        chunks.append(text)
        return "".join(chunks)


def main(argv: Optional[List[str]] = None) -> int:
    argv = argv if argv is not None else sys.argv[1:]
    if not argv:
        print("Usage: python3 openai_client.py <prompt text>", file=sys.stderr)
        return 1

    prompt = " ".join(argv)
    try:
        client = OpenAIClient()
        reply = client.send_prompt(prompt)
    except (ValueError, OpenAIError) as exc:
        print(f"Error: {exc}", file=sys.stderr)
        return 1

    print(reply)
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
